  email: string;
}

export interface WorkspaceProps {
  name: string;
  avatar?: string;
  size?: number;
}

export type CommentMentionProps = {
  user: UserProps;
  doc: DocProps;
};

export type CommentProps = {
  user: UserProps;
  doc: DocProps;
};

export type MentionProps = {
  user: UserProps;
