};

type EmailContent = {
  subject: string;
  html: string;
};

export type MailProps<T extends MailName> = Parameters<
  (typeof Renderers)[T]
>[0];

export type TeamBecomeAdminProps = {
  workspace: WorkspaceProps;
  url: string;
};

export type TeamBecomeCollaboratorProps = {
  workspace: WorkspaceProps;
  url: string;
};

export interface TeamDeleteInOneMonthProps {
  workspace: WorkspaceProps;
  expirationDate: Date;
  deletionDate: Date;
  url: string;
}

